import app from 'flarum/forum/app';
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import { t } from '../util';
/** Start a club, or rename and describe one. */
export default class ClubEditModal extends FormModal {
  name = '';
  description = '';
  oninit(vnode) {
    super.oninit(vnode);
    const club = this.attrs.club;
    this.name = club ? club.name() : '';
    this.description = club && club.description() || '';
  }
  className() {
    return 'ClubEditModal Modal--small';
  }
  title() {
    return t(this.attrs.club ? 'club.edit_title' : 'club.new_title');
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "Form"
    }, m("div", {
      className: "Form-group"
    }, m("label", {
      for: "club-name"
    }, t('club.name_label')), m("input", {
      id: "club-name",
      className: "FormControl",
      maxlength: "100",
      required: true,
      value: this.name,
      oninput: e => this.name = e.target.value
    })), m("div", {
      className: "Form-group"
    }, m("label", {
      for: "club-description"
    }, t('club.description_label')), m("textarea", {
      id: "club-description",
      className: "FormControl",
      rows: "4",
      maxlength: "2000",
      value: this.description,
      oninput: e => this.description = e.target.value
    })), m("div", {
      className: "Form-group"
    }, m(Button, {
      type: "submit",
      className: "Button Button--primary Button--block",
      loading: this.loading,
      disabled: !this.name.trim()
    }, t('club.save')))));
  }
  onsubmit(e) {
    e.preventDefault();
    this.loading = true;
    const isNew = !this.attrs.club;
    const club = this.attrs.club || app.store.createRecord('clubs');
    club.save({
      name: this.name.trim(),
      description: this.description.trim() || null
    }).then(saved => {
      this.hide();
      if (isNew) m.route.set(app.route('club', {
        id: saved.id()
      }));
    }, this.loaded.bind(this));
  }
}
flarum.reg.add('ernestdefoe-club', 'forum/components/ClubEditModal', ClubEditModal);